      size = 3.4
    ) +
    ggplot2::scale_fill_gradient2(
      low      = "#0072B2",
      mid      = "white",
      high     = "#D55E00",
      midpoint = 0,
      limits   = c(-1, 1),
      na.value = "grey92",
      name     = "r" 
    ) +
    ggplot2::facet_wrap(ggplot2::vars(set)) +
    ggplot2::coord_equal() +
    ggplot2::labs(
      x = "Test block",
